# shellcheck shell=bash disable=SC2154  # variables come from apply-theme.sh and the earlier parts
# scripts/theme.d/11-starship.sh: part of apply-theme.sh, sourced in order in the same shell (not run on its own)
# ==========================================
# 11. Starship Prompt (starship/starship.toml layout + generated palette -> ~/.cache/theme/starship.toml)
# ==========================================
cat <<EOF > "$CACHE_DIR/starship-palette.toml"

# Generated by apply-theme.sh (Color Engine)
[palettes.color_engine]
bg = "$BG"
bg_alt = "$BG_ALT"
bg_visual = "$BG_VISUAL"
fg = "$FG"
muted = "$FG_MUTED"
accent = "$ACCENT"
accent_soft = "$ACCENT_SOFT"
accent_dim = "$ACCENT_DIM"
red = "$ANSI_RED"
green = "$ANSI_GREEN"
yellow = "$ANSI_YELLOW"
cyan = "$ANSI_CYAN"
EOF
# fzf (FZF_DEFAULT_OPTS_FILE, set in cli/init.bash): read on every run, so it follows theme switches
cat <<EOF > "$CACHE_DIR/fzf.opts"
--color=fg:$FG,bg:-1,hl:$ACCENT,fg+:$FG,bg+:$BG_VISUAL,hl+:$ACCENT_SOFT,gutter:-1
--color=info:$FG_MUTED,prompt:$ACCENT,pointer:$ACCENT,marker:$ANSI_GREEN,spinner:$ACCENT_SOFT
--color=header:$ACCENT_SOFT,border:$BG_VISUAL,label:$ACCENT,query:$FG,separator:$BG_VISUAL,scrollbar:$ACCENT_DIM
--layout=reverse --height=60% --border=rounded --info=inline-right
--prompt='❯ ' --pointer='▌' --marker='+'
EOF

# Starship re-reads its config on every prompt: open terminals recolor at the next command
cat "$DOTFILES_DIR/starship/starship.toml" "$CACHE_DIR/starship-palette.toml" > "$CACHE_DIR/starship.toml"
ln -sf "$CACHE_DIR/starship.toml" "$HOME/.config/starship.toml"

